def fibonacci(n: int) -> int:
    if n < 0:
        raise ValueError("Input must be non-negative")
    def fib_pair(k):
        if k == 0:
            return (0, 1)
        a, b = fib_pair(k >> 1)
        c = a * (2 * b - a)
        d = a * a + b * b
        if k & 1:
            return (d, c + d)
        else:
            return (c, d)
    return fib_pair(n)[0]
